	@Test
	void existsSubSelectKeepsTheOwnerRowNamesItProjectsInScope() {
		// FILTER NOT EXISTS { SELECT ?x WHERE { ?t :label ?l FILTER(!BOUND(?x)) } }: the executor substitutes the
		// outer ?x into the sub-select because the sub-select projects it, so ?x is in scope; ?s is not projected.
		Filter inner = new Filter(pattern("t", "label", "l"), new Not(new Bound(new Var("x"))));
		Projection subSelect = new Projection(inner, elems("x"));
		subSelect.setSubquery(true);
		new QueryRoot(new Filter(pattern("s", "p", "x"), new Not(new Exists(subSelect))));

		OuterScope scope = BindingScopeAnalysis.outerScope(inner, Set.of());

		assertEquals(Set.of("s", "p", "x"), scope.possible());
		assertEquals(Set.of("x"), scope.possibleInScope());
	}

	@Test
	void lateralSubSelectKeepsTheSubstitutedNamesItProjectsInScope() {
		// ?s :p ?x LATERAL { SELECT ?x ?lbl WHERE { ?t :label ?lbl FILTER(!BOUND(?x) || ?t = ?x) } }: the LATERAL
		// substitutes the declared ?x into the sub-select that projects it.
		Filter inner = new Filter(pattern("t", "label", "lbl"), new Not(new Bound(new Var("x"))));
		Projection subSelect = new Projection(inner, elems("x", "lbl"));
		subSelect.setSubquery(true);
		new QueryRoot(new Projection(new Lateral(pattern("s", "p", "x"), subSelect, Set.of("x")), elems("s", "lbl")));

		OuterScope scope = BindingScopeAnalysis.outerScope(inner, Set.of());

		assertEquals(Set.of("s", "p", "x"), scope.possible());
		assertEquals(Set.of("x"), scope.possibleInScope());
	}

	private static StatementPattern pattern(String subjectName, String predicateName, String objectName) {
		return new StatementPattern(new Var(subjectName), new Var(predicateName), new Var(objectName));
	}

	private static ProjectionElemList elems(String... names) {
		ProjectionElemList list = new ProjectionElemList();
		for (String name : names) {
			list.addElement(new ProjectionElem(name));
		}
		return list;
	}
